const fs = require('fs');
const path = require('path');

const ENDPOINT = 'http://127.0.0.1:49342/status';
const OUT_DIR = path.join(__dirname, 'results');
const OUT_FILE = path.join(OUT_DIR, 'status.json');

async function main() {
  const res = await fetch(ENDPOINT);
  if (!res.ok) {
    throw new Error(`Request failed with status ${res.status}`);
  }
  const body = await res.json();
  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_FILE, JSON.stringify(body, null, 2) + '\n');
  console.log(`Wrote ${JSON.stringify(body)} to ${path.relative(__dirname, OUT_FILE)}`);
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
